head.script:


scwin.checkVal1 = function() {
    return typeof WebSquare.wUnit.getDomById('w1_input1') == 'object';
}		
scwin.checkVal2 = function() {
    return WebSquare.wUnit.getDomById('w1_input1').getAttribute('imemode') == undefined;
}		
scwin.checkVal3 = function() {
    return WebSquare.wUnit.getJq('#w1').html() == undefined;
}				
scwin.unitTest = function() {
    //Unit test
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "scwin.checkVal1()", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "scwin.checkVal2()", "true");
    WebSquare.wUnit.addCommand("pause", "500");

    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('w1').remove()");
    WebSquare.wUnit.addCommand("pause", "500");

    WebSquare.wUnit.addCommand("assert", "scwin.checkVal3()", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run and Stop test
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.unitTest();
scwin.onpageload = function() {
